const s = $input.first().json;
const REQUIRED = ['myAddress', 'telegramChatId', 'signature'];
// Stop early with a clear message if Settings still holds the template placeholders.
const unset = REQUIRED.filter(k => !String(s[k] ?? '').trim() || String(s[k]).includes('REPLACE_ME'));
if (unset.length) {
  throw new Error('Open the Settings node and fill in: ' + unset.join(', ') + '. They still contain REPLACE_ME placeholders.');
}

const lookback = Number(s.lookbackDays) || 30;
const skip = String(s.skipLabel || '').trim().replace(/\s+/g, '-');
const query = ['in:sent', `newer_than:${lookback}d`, skip ? `-label:${skip}` : ''].filter(Boolean).join(' ');

return [{ json: { ...s, waitDays: Number(s.waitDays) || 3, lookbackDays: lookback, query } }];

// Several sent messages can belong to one thread. Check each thread once.
const max = Number($('Check Settings').first().json.maxThreads) || 50;
const ids = [...new Set($input.all().map(i => i.json.threadId).filter(Boolean))].slice(0, max);
return ids.map(threadId => ({ json: { threadId } }));

const s = $('Check Settings').first().json;
const me = String(s.myAddress).toLowerCase();
const waitDays = s.waitDays;
const now = Date.now();

// Group messages by thread, whether Gmail returned whole threads or single messages.
const threads = new Map();
for (const { json } of $input.all()) {
  for (const msg of Array.isArray(json.messages) ? json.messages : [json]) {
    if (!msg || !msg.threadId) continue;
    if (!threads.has(msg.threadId)) threads.set(msg.threadId, []);
    threads.get(msg.threadId).push(msg);
  }
}

const header = (msg, name) => {
  const hit = ((msg.payload && msg.payload.headers) || []).find(h => h.name.toLowerCase() === name.toLowerCase());
  return hit ? hit.value : String(msg[name] || '');
};
const people = v =>
  [...String(v).matchAll(/(?:"?([^"<,]*?)"?\s*<([^>]+)>)|([^\s,<>"]+@[^\s,<>"]+)/g)].map(m => ({
    name: (m[1] || '').trim(),
    address: (m[2] || m[3]).toLowerCase(),
  }));
function plainText(payload) {
  if (!payload) return '';
  if (payload.mimeType === 'text/plain' && payload.body && payload.body.data) {
    return Buffer.from(payload.body.data, 'base64url').toString('utf8');
  }
  for (const part of payload.parts || []) {
    const t = plainText(part);
    if (t) return t;
  }
  return '';
}
// Drop the quoted earlier conversation, keep only what you wrote last.
function stripQuoted(text) {
  const cut = text.search(/\n(On [^\n]{0,200}wrote:|-{2,} ?Original Message|From: [^\n]+\n(Sent|Date): )/i);
  return (cut > 0 ? text.slice(0, cut) : text)
    .split('\n').filter(l => !l.startsWith('>')).join('\n')
    .replace(/\n{3,}/g, '\n\n').trim();
}

const out = [];
for (const [threadId, msgs] of threads) {
  const real = msgs
    .filter(m => !(m.labelIds || []).some(l => l === 'DRAFT' || l === 'CHAT'))
    .sort((a, b) => Number(a.internalDate) - Number(b.internalDate));
  if (!real.length) continue;
  const last = real[real.length - 1];

  // Someone else wrote last, so the thread got its answer.
  const fromMe = (last.labelIds || []).includes('SENT') || people(header(last, 'From')).some(p => p.address === me);
  if (!fromMe) continue;

  // Only real people: skip notes to yourself and no-reply addresses.
  const to = people(header(last, 'To') + ', ' + header(last, 'Cc'))
    .filter(p => p.address !== me && !/(no-?reply|do-?not-?reply|notifications?@|mailer-daemon)/i.test(p.address));
  if (!to.length) continue;

  // Remind on day waitDays, and (if repeatReminders) again every waitDays after that.
  const days = Math.floor((now - Number(last.internalDate)) / 86400000);
  if (!(days >= waitDays)) continue;
  if (s.repeatReminders ? days % waitDays !== 0 : days !== waitDays) continue;

  out.push({
    json: {
      threadId,
      subject: header(last, 'Subject') || '(no subject)',
      to: to.map(p => p.name || p.address).join(', '),
      toAddresses: to.map(p => p.address).join(', '),
      daysWaiting: days,
      lastMessage: stripQuoted(plainText(last.payload) || last.snippet || '').slice(0, 3000),
      link: `https://mail.google.com/mail/u/${s.myAddress}/#all/${threadId}`,
    },
  });
}
// Longest-waiting threads first.
out.sort((a, b) => b.json.daysWaiting - a.json.daysWaiting);
return out;

